const idKey = (value) => String(value ?? "");

const emptyRow = (player = {}) => ({
  id: idKey(player.id),
  name: player.name || "Player",
  level: player.level || "—",
  matches: 0,
  wins: 0,
  losses: 0,
  points: 0,
  snapshotPoints: Number.isFinite(Number(player.pointDifferential)) ? Number(player.pointDifferential) : 0,
  scoredFromMatches: false,
  imageUrl: player.imageUrl || player.photo || player.avatarUrl || null,
});

/** Same PD rule as live stats: margin, or 2 on a shutout. */
function pointDiffFromMatch(match) {
  const greenScore = Number(match?.score?.green);
  const blueScore = Number(match?.score?.blue);
  if (!Number.isFinite(greenScore) || !Number.isFinite(blueScore)) return null;
  if (greenScore === blueScore) return 0;
  return greenScore === 0 || blueScore === 0 ? 2 : Math.abs(greenScore - blueScore);
}

/** Rank A: more wins first, then point differential, then win rate. */
export function compareLeaderboardRows(a, b) {
  if ((b.wins || 0) !== (a.wins || 0)) return (b.wins || 0) - (a.wins || 0);
  if ((b.points || 0) !== (a.points || 0)) return (b.points || 0) - (a.points || 0);
  if ((b.winRate || 0) !== (a.winRate || 0)) return (b.winRate || 0) - (a.winRate || 0);
  if ((b.matches || 0) !== (a.matches || 0)) return (b.matches || 0) - (a.matches || 0);
  return String(a.name || "").localeCompare(String(b.name || ""));
}

/**
 * All-player leaderboard from a roster + completed matches.
 * Columns: Matches | Win Rate | Win | Lose | PD | Level
 */
export function buildPlayerLeaderboard(players = [], matches = []) {
  const stats = new Map();

  (Array.isArray(players) ? players : []).forEach((player) => {
    if (!player || player.id == null) return;
    stats.set(idKey(player.id), emptyRow(player));
  });

  (Array.isArray(matches) ? matches : []).forEach((match) => {
    if (!match || match.status !== "completed" || !match.winner) return;
    const green = Array.isArray(match.teams?.green) ? match.teams.green : [];
    const blue = Array.isArray(match.teams?.blue) ? match.teams.blue : [];
    const winner = match.winner;
    const diff = pointDiffFromMatch(match);
    [...green, ...blue].forEach((rawId) => {
      const key = idKey(rawId);
      const row = stats.get(key);
      if (!row) return;
      const onGreen = green.some((id) => idKey(id) === key);
      const won = (winner === "green" && onGreen) || (winner === "blue" && !onGreen);
      row.matches += 1;
      if (won) row.wins += 1;
      else row.losses += 1;
      if (diff != null) {
        row.scoredFromMatches = true;
        row.points += won ? diff : -diff;
      }
    });
  });

  return Array.from(stats.values())
    .map((row) => {
      const { snapshotPoints, scoredFromMatches, ...rest } = row;
      return {
        ...rest,
        points: scoredFromMatches ? row.points : snapshotPoints,
        winRate: row.matches > 0 ? Math.round((row.wins / row.matches) * 100) : 0,
      };
    })
    .sort(compareLeaderboardRows);
}

export function sliceLeaderboardTop(rows = [], n = 5) {
  return (Array.isArray(rows) ? rows : []).filter((row) => (row.matches || 0) > 0).slice(0, n);
}

export const LEADERBOARD_DISPLAY_EVENT = "SHOW_PLAYER_LEADERBOARD";
export const LEADERBOARD_DISPLAY_MS = 120000;
export const LEADERBOARD_DISPLAY_STORAGE_KEY = "southDinkersLeaderboardDisplayUntil";
export const LEADERBOARD_DISPLAY_MODE = {
  FULL: "full",
  TOP5: "top5",
};

function normalizeDisplayMode(mode) {
  return mode === LEADERBOARD_DISPLAY_MODE.TOP5
    ? LEADERBOARD_DISPLAY_MODE.TOP5
    : LEADERBOARD_DISPLAY_MODE.FULL;
}

function publishLeaderboardDisplay({ until, mode }) {
  const payload = {
    until: Number(until) || 0,
    mode: normalizeDisplayMode(mode),
  };
  try {
    if (payload.until > 0) {
      window.localStorage.setItem(LEADERBOARD_DISPLAY_STORAGE_KEY, JSON.stringify(payload));
    } else {
      window.localStorage.removeItem(LEADERBOARD_DISPLAY_STORAGE_KEY);
    }
  } catch {
    /* ignore */
  }
  if (typeof window !== "undefined" && "BroadcastChannel" in window) {
    const bc = new BroadcastChannel("dink_manager");
    bc.postMessage({ type: LEADERBOARD_DISPLAY_EVENT, until: payload.until, mode: payload.mode });
    bc.close();
  }
}

export function requestLeaderboardDisplay(
  durationMs = LEADERBOARD_DISPLAY_MS,
  mode = LEADERBOARD_DISPLAY_MODE.FULL
) {
  const until = Date.now() + durationMs;
  publishLeaderboardDisplay({ until, mode });
  return until;
}

/** Hide the TV display overlay immediately (does not overlay the admin tab). */
export function clearLeaderboardDisplay() {
  publishLeaderboardDisplay({ until: 0, mode: LEADERBOARD_DISPLAY_MODE.FULL });
}

export function readLeaderboardDisplay() {
  try {
    const raw = window.localStorage.getItem(LEADERBOARD_DISPLAY_STORAGE_KEY);
    if (!raw) return { until: 0, mode: LEADERBOARD_DISPLAY_MODE.FULL };
    if (raw.startsWith("{")) {
      const parsed = JSON.parse(raw);
      return {
        until: Number(parsed.until) || 0,
        mode: normalizeDisplayMode(parsed.mode),
      };
    }
    const n = Number(raw);
    return {
      until: Number.isFinite(n) ? n : 0,
      mode: LEADERBOARD_DISPLAY_MODE.FULL,
    };
  } catch {
    return { until: 0, mode: LEADERBOARD_DISPLAY_MODE.FULL };
  }
}

export function readLeaderboardDisplayUntil() {
  return readLeaderboardDisplay().until;
}

export function remainingLeaderboardDisplayMs(now = Date.now()) {
  return Math.max(0, readLeaderboardDisplayUntil() - now);
}
