import config from "../../config";

const API_BASE = process.env.REACT_APP_API_URL || "";
const FACILITY_ID = process.env.REACT_APP_FACILITY_ID || config.facilityId;

const parseJson = async (res) => {
  try {
    return await res.json();
  } catch {
    return {};
  }
};

export async function verifyLockPin(pin) {
  const res = await fetch(`${API_BASE}/api/v1/facilities/${FACILITY_ID}/verify-pin`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ pin }),
  });
  const data = await parseJson(res);
  if (!res.ok) {
    const err = new Error(data.message || data.error || "Could not verify PIN");
    err.code = data.error;
    throw err;
  }
  return data;
}

export async function changeLockPin({ oldPin, newPin, confirmPin }) {
  const res = await fetch(`${API_BASE}/api/v1/facilities/${FACILITY_ID}/pin`, {
    method: "PUT",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ oldPin, newPin, confirmPin }),
  });
  const data = await parseJson(res);
  if (!res.ok) {
    const err = new Error(data.message || data.error || "Could not change PIN");
    err.code = data.error;
    throw err;
  }
  return data;
}
