import React, { useEffect, useState } from "react";
import config from "../../../config";
import LevelAvatar from "../../queue/components/LevelAvatar";

const PODIUM_ORDER = [1, 0, 2]; // visual: 2nd, 1st, 3rd
const RANK_GLOW = [
  "0 0 22px 8px rgba(255, 215, 0, 0.45), 0 0 48px 14px rgba(196, 92, 58, 0.32)",
  "0 0 18px 6px rgba(192, 197, 206, 0.35), 0 0 34px 10px rgba(201, 165, 130, 0.2)",
  "0 0 18px 6px rgba(196, 92, 58, 0.4), 0 0 34px 10px rgba(139, 58, 36, 0.25)",
];
const RANK_GLOW_PEAK = [
  "0 0 32px 12px rgba(255, 215, 0, 0.55), 0 0 64px 18px rgba(196, 92, 58, 0.32)",
  "0 0 28px 10px rgba(192, 197, 206, 0.5), 0 0 48px 14px rgba(201, 165, 130, 0.28)",
  "0 0 28px 10px rgba(196, 92, 58, 0.55), 0 0 48px 14px rgba(139, 58, 36, 0.3)",
];
const RANK_RING = ["#FFD700", "#C0C5CE", "#C45C3A"];

function formatPd(value) {
  const n = Number(value) || 0;
  return n > 0 ? `+${n}` : String(n);
}

function useOverlayAutoClose(until, onClose) {
  useEffect(() => {
    let closed = false;
    const tick = () => {
      if (Date.now() >= until && !closed) {
        closed = true;
        onClose?.();
      }
    };
    tick();
    const id = setInterval(tick, 250);
    return () => clearInterval(id);
  }, [until, onClose]);
}

function OverlayClock() {
  const [now, setNow] = useState(() => new Date());
  useEffect(() => {
    const id = setInterval(() => setNow(new Date()), 1000);
    return () => clearInterval(id);
  }, []);

  return (
    <div className="text-right leading-none">
      <div className="text-4xl md:text-5xl font-condensed font-bold text-white tabular-nums drop-shadow-md">
        {now.toLocaleTimeString("en-PH", { hour: "2-digit", minute: "2-digit", second: "2-digit", hour12: true })}
      </div>
      <div className="text-base text-white/80 uppercase tracking-widest mt-2 font-medium">
        {now.toLocaleDateString("en-PH", { weekday: "short", month: "short", day: "numeric" })}
      </div>
    </div>
  );
}

function StatBlock({ label, value, color, large }) {
  return (
    <div className="min-w-0 text-center px-2">
      <p className={`uppercase tracking-[0.18em] text-white/40 ${large ? "text-xs" : "text-[10px]"}`}>{label}</p>
      <p
        className={`font-condensed font-black tabular-nums mt-1 ${large ? "text-3xl md:text-4xl" : "text-2xl md:text-3xl"}`}
        style={{ color }}
      >
        {value}
      </p>
    </div>
  );
}

function RankStats({ row, large }) {
  return (
    <div className="flex items-end justify-center gap-4 md:gap-8">
      <StatBlock label="Win rate" value={`${row.winRate}%`} color="#FFD700" large={large} />
      <StatBlock label="Record" value={`${row.wins}–${row.losses}`} color="rgba(255,255,255,0.88)" large={large} />
      <StatBlock label="PD" value={formatPd(row.points)} color="#C45C3A" large={large} />
    </div>
  );
}

function PlayerCard({ row, rank, featured }) {
  const isPodium = rank <= 3;
  const size = featured ? 220 : isPodium ? 168 : 108;
  const ring = isPodium ? RANK_RING[rank - 1] : "#C9A582";

  if (!isPodium) {
    return (
      <div
        className="h-full min-h-0 flex items-center gap-8 rounded-3xl border px-8 py-5"
        style={{
          background: "rgba(255,255,255,0.03)",
          borderColor: "rgba(255,255,255,0.08)",
        }}
      >
        <span className="w-24 shrink-0 text-center font-condensed font-black text-6xl leading-none text-[#C9A582]">
          #{rank}
        </span>
        <LevelAvatar
          src={row.imageUrl}
          alt={row.name}
          fallback={row.name}
          frameColor={ring}
          size={size}
          ring={5}
          background="#fff"
        />
        <div className="flex-1 min-w-0">
          <p className="font-condensed font-black uppercase tracking-wide text-white truncate text-3xl md:text-4xl">
            {row.name}
          </p>
          <p className="text-sm uppercase tracking-[0.18em] text-white/45 mt-2">{row.level || "—"}</p>
        </div>
        <div className="shrink-0">
          <RankStats row={row} />
        </div>
      </div>
    );
  }

  return (
    <div
      className="h-full min-h-0 flex flex-col rounded-3xl border px-8 py-7"
      style={{
        background: featured
          ? "linear-gradient(180deg, rgba(196,92,58,0.18) 0%, rgba(18,24,38,0.95) 45%)"
          : "rgba(255,255,255,0.04)",
        borderColor: `${ring}66`,
        animation: "sdPodiumGlow 2.6s ease-in-out infinite",
        boxShadow: RANK_GLOW[rank - 1],
        "--sd-glow": RANK_GLOW[rank - 1],
        "--sd-glow-peak": RANK_GLOW_PEAK[rank - 1],
      }}
    >
      <span className="font-condensed font-black text-[#C9A582]/85 leading-none" style={{ fontSize: featured ? "3rem" : "2.25rem" }}>
        #{rank}
      </span>
      <div className="flex-1 min-h-0 flex flex-col items-center justify-center text-center gap-5">
        <LevelAvatar
          src={row.imageUrl}
          alt={row.name}
          fallback={row.name}
          frameColor={ring}
          size={size}
          ring={featured ? 6 : 5}
          background="#fff"
        />
        <div className="min-w-0 w-full">
          <p
            className={`font-condensed font-black uppercase tracking-wide text-white truncate ${
              featured ? "text-5xl" : "text-4xl"
            }`}
          >
            {row.name}
          </p>
          <p className="text-sm uppercase tracking-[0.2em] text-white/45 mt-2">{row.level || "—"}</p>
        </div>
        <RankStats row={row} large={featured} />
      </div>
    </div>
  );
}

export default function PlayerLeaderboardTop5Overlay({ rows = [], until, onClose }) {
  const top5 = rows.slice(0, 5);
  const podium = top5.slice(0, 3);
  const rest = top5.slice(3);
  useOverlayAutoClose(until, onClose);

  return (
    <div className="fixed inset-0 z-[80] bg-[#070b12] flex flex-col p-6 md:p-8">
      <style>{`
        @keyframes sdPodiumGlow {
          0%, 100% { box-shadow: var(--sd-glow); }
          50% { box-shadow: var(--sd-glow-peak); }
        }
      `}</style>
      <header className="flex items-center justify-between mb-5 px-2 shrink-0">
        <div className="flex items-center gap-5">
          <img
            src={config.assetPath("logo.png")}
            alt={config.name}
            className="h-16 md:h-24 w-auto object-contain"
          />
          <div className="flex flex-col leading-none">
            <h2 className="text-2xl md:text-4xl text-white font-bold tracking-wide">Top 5 Players</h2>
            <p className="text-[10px] text-[#C9A582] uppercase tracking-[0.3em] mt-1 font-medium">
              {config.tagline || "Sports Center"}
            </p>
          </div>
        </div>
        <OverlayClock />
      </header>
      <div className="h-px bg-gradient-to-r from-transparent via-[#C45C3A]/40 to-transparent mb-5 mx-2 shrink-0" />

      {top5.length === 0 ? (
        <div className="flex-1 flex items-center justify-center text-white/40 uppercase tracking-[0.2em] text-sm">
          No completed matches yet.
        </div>
      ) : (
        <div className="flex-1 min-h-0 flex flex-col gap-6 w-full">
          <div className="flex-[3] min-h-0 grid grid-cols-3 gap-6">
            {PODIUM_ORDER.map((idx) => {
              const row = podium[idx];
              if (!row) return <div key={idx} />;
              const rank = idx + 1;
              return (
                <div key={row.id} className={`min-h-0 ${rank === 1 ? "order-2" : rank === 2 ? "order-1" : "order-3"}`}>
                  <PlayerCard row={row} rank={rank} featured={rank === 1} />
                </div>
              );
            })}
          </div>
          {rest.length > 0 && (
            <div className="flex-[1.15] min-h-0 grid grid-cols-1 md:grid-cols-2 gap-6">
              {rest.map((row, i) => (
                <PlayerCard key={row.id} row={row} rank={i + 4} />
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}
