import { CURRENT_STATE_VERSION, normalizeStateMeta, withStateEnvelope } from "./schema";

// A helper to save/load from localStorage with basic versioning metadata
// Storage key is client-specific so each client deployment has isolated state
// Open Play History (opSessions) is browser-local: localStorage + IndexedDB backup.
// Calendar bookings are NOT stored here — they come from Neon.

export const APP_STORAGE_KEY = "southDinkersAppState";
const IDB_NAME = "southDinkersApp";
const IDB_STORE = "kv";
const IDB_VERSION = 1;
const FULL_SESSION_KEEP = 8;

const getStorageKey = () => APP_STORAGE_KEY;

const getStorage = () => {
  if (typeof window !== "undefined" && window.localStorage) {
    return window.localStorage;
  }
  return null;
};

const CALENDAR_PERSIST_KEYS = ["bookings", "calendarCourts", "bookingsV2", "slotsV2"];

const supportsIndexedDB = () =>
  typeof indexedDB !== "undefined" && indexedDB !== null;

export function isQuotaExceededError(err) {
  if (!err) return false;
  return (
    err.name === "QuotaExceededError" ||
    err.name === "NS_ERROR_DOM_QUOTA_REACHED" ||
    err.code === 22 ||
    err.code === 1014
  );
}

function sanitizeState(state = {}) {
  const sanitized = { ...state };
  CALENDAR_PERSIST_KEYS.forEach((key) => {
    delete sanitized[key];
  });
  delete sanitized.isDemoMode;
  return sanitized;
}

function parsePersistedRaw(raw) {
  if (!raw) return null;
  const parsed = typeof raw === "string" ? JSON.parse(raw) : raw;
  if (!parsed || typeof parsed !== "object") return null;

  const legacyMeta = parsed.meta || {};
  const normalizedMeta = normalizeStateMeta({
    ...legacyMeta,
    seededAt: legacyMeta.seededAt || parsed.seededAt || null,
    seedSource: legacyMeta.seedSource || parsed.seedSource || null,
    seedLabel: legacyMeta.seedLabel || parsed.seedLabel || null,
    lastSavedAt:
      legacyMeta.lastSavedAt ||
      legacyMeta.savedAt ||
      parsed.lastSavedAt ||
      parsed.savedAt ||
      null,
    stateVersion: legacyMeta.stateVersion || parsed.version || CURRENT_STATE_VERSION,
  });

  const sanitized = sanitizeState(parsed);
  return {
    ...sanitized,
    meta: normalizedMeta,
    version: parsed.version || CURRENT_STATE_VERSION,
  };
}

export function getStateSavedAt(state) {
  const raw = state?.meta?.lastSavedAt || state?.lastSavedAt || state?.savedAt || null;
  if (!raw) return 0;
  const t = new Date(raw).getTime();
  return Number.isFinite(t) ? t : 0;
}

/** Shrink older Open Play snapshots so History rows still exist under localStorage quota. */
export function compactOpSessionsForStorage(sessions = []) {
  if (!Array.isArray(sessions) || sessions.length <= FULL_SESSION_KEEP) {
    return sessions;
  }
  const indexed = sessions.map((s, i) => ({ s, i }));
  indexed.sort((a, b) => {
    const tb = b.s?.endedAt || b.s?.startedAt || 0;
    const ta = a.s?.endedAt || a.s?.startedAt || 0;
    if (tb !== ta) return tb - ta;
    return b.i - a.i;
  });
  const keepFull = new Set(indexed.slice(0, FULL_SESSION_KEEP).map((x) => x.i));
  return sessions.map((s, i) => {
    if (keepFull.has(i) || !s) return s;
    const matches = Array.isArray(s.matches) ? s.matches : [];
    return {
      ...s,
      matches: [],
      totalMatches: s.totalMatches || matches.length,
    };
  });
}

function openStateDb() {
  return new Promise((resolve, reject) => {
    if (!supportsIndexedDB()) {
      reject(new Error("IndexedDB unavailable"));
      return;
    }
    const req = indexedDB.open(IDB_NAME, IDB_VERSION);
    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains(IDB_STORE)) {
        db.createObjectStore(IDB_STORE);
      }
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error || new Error("IndexedDB open failed"));
  });
}

function idbSet(serialized) {
  if (!supportsIndexedDB()) return Promise.resolve(false);
  return openStateDb()
    .then(
      (db) =>
        new Promise((resolve, reject) => {
          const tx = db.transaction(IDB_STORE, "readwrite");
          tx.oncomplete = () => {
            db.close();
            resolve(true);
          };
          tx.onerror = () => {
            db.close();
            reject(tx.error);
          };
          tx.objectStore(IDB_STORE).put(serialized, getStorageKey());
        })
    )
    .catch((err) => {
      console.error("IndexedDB save failed", err);
      return false;
    });
}

function idbGet() {
  if (!supportsIndexedDB()) return Promise.resolve(null);
  return openStateDb()
    .then(
      (db) =>
        new Promise((resolve, reject) => {
          const tx = db.transaction(IDB_STORE, "readonly");
          const req = tx.objectStore(IDB_STORE).get(getStorageKey());
          req.onsuccess = () => {
            db.close();
            resolve(req.result || null);
          };
          req.onerror = () => {
            db.close();
            reject(req.error);
          };
        })
    )
    .catch((err) => {
      console.error("IndexedDB load failed", err);
      return null;
    });
}

function writeLocalStorage(serialized) {
  const storage = getStorage();
  if (!storage) {
    throw new Error("Local storage unavailable");
  }
  storage.setItem(getStorageKey(), serialized);
}

/**
 * Persist app state to localStorage (sync) and IndexedDB (async backup).
 * On quota errors, compact older session match lists and retry.
 * Returns { ok, payload, compacted, error, localStorageOk, indexedDbPending }.
 */
export function persistAppState(state = {}) {
  const result = {
    ok: false,
    payload: null,
    compacted: false,
    error: null,
    localStorageOk: false,
  };

  try {
    const payload = withStateEnvelope(sanitizeState(state));
    let toStore = payload;
    let serialized = JSON.stringify(toStore);

    try {
      writeLocalStorage(serialized);
      result.localStorageOk = true;
    } catch (err) {
      if (!isQuotaExceededError(err)) {
        throw err;
      }
      const compactedSessions = compactOpSessionsForStorage(payload.opSessions || []);
      toStore = withStateEnvelope({ ...payload, opSessions: compactedSessions });
      serialized = JSON.stringify(toStore);
      writeLocalStorage(serialized);
      result.localStorageOk = true;
      result.compacted = true;
    }

    result.payload = toStore;
    result.ok = true;
    void idbSet(serialized);
    return result;
  } catch (err) {
    console.error("Failed to save state", err);
    result.error = err;
    // Last resort: still try IndexedDB so History can recover on reload.
    try {
      const fallback = withStateEnvelope(sanitizeState(state));
      result.payload = fallback;
      void idbSet(JSON.stringify(fallback));
    } catch (idbErr) {
      console.error("IndexedDB fallback also failed", idbErr);
    }
    return result;
  }
}

export function saveState(state = {}) {
  return persistAppState(state).payload;
}

export function loadState() {
  try {
    const storage = getStorage();
    if (!storage) return null;
    return parsePersistedRaw(storage.getItem(getStorageKey()));
  } catch (err) {
    console.error("Failed to load state", err);
    return null;
  }
}

/** Async IndexedDB read. Used to recover Open Play History when localStorage is stale or over quota. */
export async function loadStateFromIndexedDB() {
  try {
    const raw = await idbGet();
    return parsePersistedRaw(raw);
  } catch (err) {
    console.error("Failed to load IndexedDB state", err);
    return null;
  }
}

export function pickNewerState(a, b) {
  if (!a) return b || null;
  if (!b) return a;
  return getStateSavedAt(b) > getStateSavedAt(a) ? b : a;
}

function sessionFreshness(session) {
  if (!session) return 0;
  const players = Array.isArray(session.players) ? session.players.length : 0;
  const matches = Array.isArray(session.matches) ? session.matches.length : 0;
  const completed = String(session.status || "").toLowerCase() === "completed" ? 1_000_000 : 0;
  return completed + players * 100 + matches + (session.endedAt || session.startedAt || 0) / 1e13;
}

/** Union local + IndexedDB sessions by id so History cannot drop a just-ended snapshot. */
export function mergeOpSessions(local = [], remote = []) {
  const map = new Map();
  [...(Array.isArray(local) ? local : []), ...(Array.isArray(remote) ? remote : [])].forEach((s) => {
    if (!s?.id) return;
    const existing = map.get(s.id);
    if (!existing || sessionFreshness(s) >= sessionFreshness(existing)) {
      map.set(s.id, s);
    }
  });
  return Array.from(map.values());
}

